import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"1995年 · 双管齐下","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1995年.md","filePath":"05_quotes/by-year/1995年.md"}'),l={name:"05_quotes/by-year/1995年.md"};function u(c,e,p,q,s,_){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_1995年-·-双管齐下" tabindex="-1">1995年 · 双管齐下 <a class="header-anchor" href="#_1995年-·-双管齐下" aria-label="Permalink to &quot;1995年 · 双管齐下&quot;">​</a></h1><blockquote><p>套用肯尼迪总统的话说，涨潮时所有游艇都会水涨船高。——巴菲特（65岁）</p></blockquote><p>本页收录1995年致股东信中的经典语录。本年伯克希尔完成三笔重大收购——GEICO、赫尔兹伯格钻石店和R.C.威利家居，巴菲特系统阐述了&quot;双管齐下&quot;的资本配置策略，并以自身教训强调了用股票收购的代价。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>查理和我希望构建一个由杰出管理者经营、具有卓越经济特征的公司集合——无论是全资拥有还是部分持有。</p></blockquote><blockquote><p>在零售业，停滞不前就是失败。</p></blockquote><blockquote><p>在商业中，我寻找由不可逾越的&quot;护城河&quot;保护的经济城堡。</p></blockquote><blockquote><p>如果你的余生都要吃汉堡，而且你不是牛肉生产者，你应该希望牛肉价格更高还是更低？同样，如果你不时购买汽车但不是汽车制造商，你应该更喜欢更高还是更低的汽车价格？……只有那些在近期将成为股票净卖家的人才应该在股票上涨时感到高兴。潜在买家应该更乐意看到价格下跌。</p></blockquote><blockquote><p>在收购方面，我们有一个优势：作为支付手段，我们可以向卖方提供由一批卓越企业支撑的股票。</p></blockquote><blockquote><p>我们像其他有收购意向的公司一样，在预测未来方面面临着所有困难。和他们一样，我们也面临一个固有的问题：卖方几乎总是比买方更了解自己的企业，而且会选择出售的时机——一个企业很可能&quot;走得好好的&quot;的时候。</p></blockquote><blockquote><p>卖出一家可辨识的卓越公司的股权是不明智的。</p></blockquote><blockquote><p>最棒的则是，我们不仅限于拥有这一类型的少数几家公司，而是拥有一个不断增长的收藏。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1995年伯克希尔净资产增长45%，完成GEICO全部股权收购、赫尔兹伯格钻石店和R.C.威利家居的收购，收入翻倍但总部仅增加1人。巴菲特宣布创建B类股票以阻止市场上以伯克希尔名义发行的高费用单位信托，并坦承当时股价未被低估。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1995年/翻译.html">01_letters/1995年/翻译</a> · <a href="/01_letters/1995年/核心总结.html">01_letters/1995年/核心总结</a> · <a href="/01_letters/1995年/思维导图.html">01_letters/1995年/思维导图</a></p>',19)])])}const n=t(l,[["render",u]]);export{b as __pageData,n as default};
